import math

def get_N_beatty(alpha, limit=100):
    beta = 1 / (1 - 1/alpha)
    f = [[0] * limit for _ in range(limit)]
    f[0][0] = 1
    for x in range(1, limit):
        f[x][0] = math.floor(f[x-1][0] * alpha)
    for y in range(1, limit):
        for x in range(limit):
            f[x][y] = math.floor(f[x][y-1] * beta)

    count = 0
    for x in range(limit):
        for y in range(limit):
            if f[x][y] % 2 == 0:
                count += 1
    return count

